  function taskCalendar(items,mini=false){const parts=calendarMonth.split('-').map(Number),y=parts[0],m=parts[1];const first=(new Date(y,m-1,1).getDay()+6)%7;const count=new Date(y,m,0).getDate();const cells=[];for(let i=0;i<first;i++)cells.push('<div class="j-cal-empty"></div>');for(let d=1;d<=count;d++){const dt=`${calendarMonth}-${String(d).padStart(2,'0')}`;const onDay=items.filter(t=>t.due===dt),isToday=dt===day();cells.push(`<button type="button" class="j-cal-day ${dt===selectedDay?'selected':''} ${isToday?'today':''}" data-j="calendar-day" data-date="${dt}"><span>${d}</span>${onDay.length?`<b>${onDay.length}</b>`:''}${!mini?onDay.slice(0,2).map(t=>`<small>${E(t.name)}</small>`).join(''):''}</button>`)}const dateLabel=new Date(y,m-1,1).toLocaleDateString('pl-PL',{month:'long',year:'numeric'});return `<div class="j-calendar ${mini?'mini':''}"><div class="j-calendar-head"><strong>${E(dateLabel)}</strong><div><button type="button" data-j="calendar-nav" data-shift="-1" aria-label="Poprzedni miesiąc">‹</button><button type="button" data-j="calendar-nav" data-shift="1" aria-label="Następny miesiąc">›</button></div></div><div class="j-calendar-grid">${['Pn','Wt','Śr','Cz','Pt','So','Nd'].map(v=>`<span class="j-weekday">${v}</span>`).join('')}${cells.join('')}</div><div class="j-calendar-agenda"><strong>${E(selectedDay)}</strong>${items.filter(t=>t.due===selectedDay).map(t=>`<div class="j-line"><div><strong>${E(t.name)}</strong><small>${E(stageTask(t))} · ${E(t.owner||'—')}</small></div>${button('task','Otwórz',t.id)}</div>`).join('')||'<p class="j-help">Brak zadań na wybrany dzień.</p>'}</div></div>`}
