  function renderTasks(){const list=active('tasks').filter(t=>taskOwner==='team'||t.owner===taskOwner).filter(t=>taskFilter==='all'||(taskFilter==='project'?!!t.projectId:!t.projectId));$('content').innerHTML=hero('MISSION CONTROL / TASKS','Zadania','Kanban, tabela i kalendarz korzystają z jednego statusu. Kliknij kartę, aby poprawić opis, właściciela i deadline.',button('new-task','+ Nowe zadanie','','primary'))+`<div class="j-toolbar"><label>Operator <select data-j-change="task-owner">${options(['team','Kari','Adi'],taskOwner)}</select></label><label>Obszar <select data-j-change="task-filter">${options(['all','project','other'],taskFilter)}</select></label>${taskTabs(taskMode)}</div>${taskMode==='board'?taskBoard(list):taskMode==='list'?taskList(list):taskCalendar(list)}`;}
