  const range=(period=moneyPeriod,now=new Date())=>{const e=day(now);if(period==='all')return {start:'0000-01-01',end:'9999-12-31',label:'Cała historia'};const d=new Date(now.getFullYear(),now.getMonth(),now.getDate());if(period==='week')d.setDate(d.getDate()-(d.getDay()+6)%7);else d.setDate(d.getDate()-29);return {start:day(d),end:e,label:period==='week'?'Ten tydzień':'Ostatnie 30 dni'}};
  const inRange=(v,r)=>!!v&&String(v).slice(0,10)>=r.start&&String(v).slice(0,10)<=r.end;
  const sums=items=>{const map={};for(const x of items){const amount=Number(x.amount||0);if(!Number.isFinite(amount)||amount===0)continue;const c=String(x.currency||'PLN').toUpperCase();map[c]=(map[c]||0)+amount}return map};
